//! `pf rules sync`: one path-scoped Claude Code rule per descriptor module, at
//! `<repo>/.claude/rules/modules/<area>.md`. Each rule loads only when Claude works on
//! files under that module, and routes it to the module's own instructions and gates.
//! The files are generated, so edit the descriptor or the module's `AGENTS.md`, never the rule.

use std::fs;
use std::path::{Path, PathBuf};

use crate::descriptor::{self, Descriptor, Map};
use crate::{discovery, util};

pub const MARK: &str =
    "<!-- generated by pf rules sync from .factory/factory.yaml; do not edit -->";

fn val<'a>(m: &'a Map, k: &str, default: &'a str) -> &'a str {
    m.get(k)
        .map(String::as_str)
        .filter(|v| !v.is_empty())
        .unwrap_or(default)
}

pub fn render(d: &Descriptor, m: &Map) -> String {
    let area = val(m, "area", "module");
    let path = val(m, "path", ".").trim_end_matches('/');
    let agents = val(m, "agents_md", "AGENTS.md");
    let base = d.module_vcs(m, "base_branch").unwrap_or("main");
    let host = d.module_vcs(m, "host").unwrap_or("github");
    let tests = match val(m, "tests", "yes") {
        "no" => {
            "**forbidden**: this module has a no-unit-test policy. Use its static gates and documented manual acceptance, and never add test infrastructure"
        }
        _ => "follow the module's conventions",
    };
    let request = if host == "gitlab" { "MR" } else { "PR" };
    format!(
        "---\npaths:\n  - \"{path}/**\"\n---\n\n# Module `{area}` ({path}/)\n\n{MARK}\n\n\
When you work on files under `{path}/`:\n\n\
- `{path}/{agents}` and `{path}/CLAUDE.md` are authoritative for this module. Read them\n  before editing, and follow them over anything general.\n\
- Owner role: `{owner}`. Gates: {gates}.\n\
- Unit tests: {tests}.\n\
- Factory jobs in the owning Git checkout branch `{branch}` from `{base}`\n  in a worktree outside the workspace, and open an {request} on {host} to `{base}`.\n  Commits follow `{commits}` conventions, and this repo's hooks and CI checks always run.\n\
- Do not edit a sibling module from here. Cross-module work is split into one\n  factory job per module.\n",
        branch = d
            .get("vcs.branch_template")
            .unwrap_or("factory/{job-id}")
            .replace("{job-id}", "<job-id>"),
        commits = d.get("vcs.commit_convention").unwrap_or("the repo's"),
        owner = val(m, "owner_role", "engineer"),
        gates = val(m, "gates", "see the module's AGENTS.md"),
    )
}

/// Write the rule files. Returns (written paths, removed stale paths).
pub fn sync(d: &Descriptor) -> std::io::Result<(Vec<PathBuf>, Vec<PathBuf>)> {
    let relative = Path::new(".claude/rules/modules");
    let dir = d.root.join(relative);
    let mut written = Vec::new();
    let mut removed = Vec::new();
    if !d.multi_repo() {
        return Ok((written, removed));
    }
    if !discovery::local_path(&d.root, relative) {
        return Err(std::io::Error::other("Unsafe module rules directory"));
    }
    let mut keep = Vec::new();
    for m in &d.modules {
        let area = val(m, "area", "module");
        let name = format!("{area}.md");
        let path = relative.join(&name);
        if Path::new(&name).components().count() != 1
            || !discovery::local_path(&d.root, &path)
            || keep.contains(&d.root.join(&path))
        {
            return Err(std::io::Error::other(format!(
                "Invalid or duplicate module rule name: {area}"
            )));
        }
        let file = d.root.join(path);
        match fs::read_to_string(&file) {
            Ok(text) if text.lines().any(|line| line == MARK) => (),
            Ok(_) => {
                return Err(std::io::Error::other(format!(
                    "Unmanaged module rule: {}",
                    file.display()
                )));
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => (),
            Err(e) => return Err(e),
        }
        keep.push(file);
    }
    fs::create_dir_all(&dir)?;
    for (m, f) in d.modules.iter().zip(&keep) {
        let text = render(d, m);
        if fs::read_to_string(f).ok().as_deref() != Some(&text) {
            fs::write(f, text)?;
            written.push(f.clone());
        }
    }
    for e in fs::read_dir(&dir)?.flatten() {
        let p = e.path();
        if !keep.contains(&p)
            && e.file_type()?.is_file()
            && fs::read_to_string(&p).is_ok_and(|t| t.lines().any(|line| line == MARK))
        {
            fs::remove_file(&p)?;
            removed.push(p);
        }
    }
    Ok((written, removed))
}

/// Missing or stale module rules, for `pf doctor`.
pub fn check(d: &Descriptor) -> Vec<String> {
    if !d.multi_repo() {
        return vec![];
    }
    d.modules
        .iter()
        .filter_map(|m| {
            let f = d.root.join(format!(
                ".claude/rules/modules/{}.md",
                val(m, "area", "module")
            ));
            (fs::read_to_string(&f).ok().as_deref() != Some(render(d, m).as_str()))
                .then(|| util::rel(&d.root, &f))
        })
        .collect()
}

pub fn main(root: Option<PathBuf>) -> i32 {
    let start = root.unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
    let Some(d) = descriptor::find(&start) else {
        eprintln!("pf: no .factory/factory.yaml here or in a parent folder");
        return 1;
    };
    if !d.multi_repo() {
        println!("single-repo descriptor: no module rules needed");
        return 0;
    }
    match sync(&d) {
        Ok((w, r)) => {
            for p in &w {
                println!("wrote {}", util::rel(&d.root, p));
            }
            for p in &r {
                println!("removed stale {}", util::rel(&d.root, p));
            }
            0
        }
        Err(e) => {
            eprintln!("pf: {e}");
            1
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn renders_a_path_scoped_rule() {
        let d = descriptor::parse(
            "layout: multi-repo\nmodules:\n  - area: backend\n    path: services/api\n    tests: no\nvcs:\n  host: gitlab\n  base_branch: develop\n",
        );
        let r = render(&d, &d.modules[0]);
        assert!(r.starts_with("---\npaths:\n  - \"services/api/**\"\n---\n"));
        assert!(r.contains("no-unit-test policy"));
        assert!(r.contains("open an MR on gitlab to `develop`"));
    }
}
